typedef float rational_t;
typedef float time_value_t;

class vector3d
{
public:
  rational_t x, y, z;
};

extern const vector3d ZEROVEC;

class entity;

class anim_control_t
{
  time_value_t current_time;
  time_value_t time_delta;
  time_value_t duration;
  rational_t timescale_factor;
  rational_t cntrl_tween_duration;
  rational_t tween_timer;
  unsigned int flags;
  short loop_count;

public:
  inline bool is_flagged(unsigned int f) const { return (flags & f); }
  inline bool is_reverse() const { return is_flagged(0x0002); }
  inline bool is_looping() const { return is_flagged(0x0004); }
  inline bool is_finished() const
  {
    if ( is_looping() && (loop_count==-1 || loop_count>0) )
      return false;
    if ( is_reverse() )
      return ( current_time <= 0 );
    else
      return ( current_time >= duration );
  }
};

class entity_anim_tree
{
  unsigned short flags;
  char padding0[70];
  anim_control_t control;
  char padding1[6];
  rational_t floor_offset;

public:
  inline bool is_finished() const { return control.is_finished(); }
  inline bool is_relative_to_start() const { return (flags & 0x0001); }
  inline rational_t get_floor_offset() const { return floor_offset; }
  bool is_root(entity *value) const;
  void get_current_root_relpos(vector3d *position) const;
};

class entity
{
public:
  entity_anim_tree *get_anim_tree(int slot) const;
};

class physical_interface
{
  void *vtable;
protected:
  entity *my_entity;
  char padding[164];
  rational_t last_floor_offset;

public:
  inline entity *get_my_entity() const { return my_entity; }
  rational_t get_floor_offset();
};

asm(".equ ZEROVEC, 0x00513840");
asm(".equ get_anim_tree__C6entityi, 0x001348D8");
asm(".equ is_root__C16entity_anim_treeP6entity, 0x00118598");
asm(".equ get_current_root_relpos__C16entity_anim_treeP8vector3d, 0x00118510");

// return desired distance from character's root to floor
rational_t physical_interface::get_floor_offset()
{
  // for now at least, this is entirely determined by the root animation
  entity_anim_tree* a = 0;

  for(int i=(10-1); i>=0 && (a == 0); --i)
//  for(int i=0; i<10 && (a == 0); ++i)
  {
    a = my_entity->get_anim_tree( i );
    if(a && (a->is_finished() || a->get_floor_offset() <= 0.0f || !a->is_root(get_my_entity())))
      a = 0;
  }

  if ( a!=0 && a->is_relative_to_start() )
  {
    vector3d relp = ZEROVEC;
    a->get_current_root_relpos( &relp );
    last_floor_offset = a->get_floor_offset();

    last_floor_offset += relp.y;
  }
  return last_floor_offset;
}
